@Configuration
public class AppConfig {
    @Bean
    @Scope("singleton")  // This becomes part of bean definition
    public UserRepository userRepository() {
        return new UserRepository();
    }

    @Bean(initMethod = "initialize")  // Lifecycle metadata in definition
    public UserService userService(UserRepository repo) {
        var service = new UserService(repo);
        service.setMaxRetries(3);  // Property value in definition
        return service;
    }
}

@Service  // Spring creates a bean definition from this annotation
public class OrderService {
    private final UserService userService;

    public OrderService(UserService userService) {  // Constructor arg in definition
        this.userService = userService;
    }
}

@Configuration
public class AppConfig {

    @Bean  // Method name becomes bean name: "objectMapper"
    public ObjectMapper objectMapper() {
        var mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());  // Custom config
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;  // This instance is now a Spring bean
    }

    @Bean(name = "mainDataSource")  // Custom bean name
    public DataSource dataSource() {
        var config = new HikariConfig();
        config.setJdbcUrl("jdbc:postgresql://localhost/mydb");
        config.setUsername("user");
        config.setMaximumPoolSize(10);
        return new HikariDataSource(config);  // Third-party class
    }

    @Bean
    public UserService userService(UserRepository repo, ObjectMapper mapper) {
        return new UserService(repo, mapper);  // Spring injects params
    }
}

@Component
public class DatabaseSchemaInitializer {
    public DatabaseSchemaInitializer(DataSource dataSource) {
        // Runs SQL scripts to create tables
        executeSchemaDDL(dataSource);
    }

    private void executeSchemaDDL(DataSource ds) {
        // Creates tables, indexes — side effect, no return value
    }
}

@Repository
@DependsOn("databaseSchemaInitializer")  // Forces init order
public class OrderRepository {
    private final JdbcTemplate jdbcTemplate;

    public OrderRepository(DataSource dataSource) {
        this.jdbcTemplate = new JdbcTemplate(dataSource);
        // Queries tables — must exist first
    }

    public List<Order> findAll() {
        return jdbcTemplate.query("SELECT * FROM orders", 
            (rs, row) -> new Order(rs.getLong("id"), rs.getString("item")));
    }
}

@Service  // Default name: "userService"
public class UserService {
    private final UserRepository userRepository;

    public UserService(UserRepository repo) {  // Injected by type
        this.userRepository = repo;
    }
}

@Repository("mainUserRepo")  // Custom name
public class UserRepository {}

@Configuration
public class DatabaseConfig {

    @Bean  // Default name: "primaryDataSource"
    public DataSource primaryDataSource() {
        return new HikariDataSource(primaryConfig());
    }

    @Bean(name = "reportingDataSource")  // Custom name for second DataSource
    public DataSource reportingDataSource() {
        return new HikariDataSource(reportingConfig());
    }
}

@Service
public class ReportService {
    private final DataSource dataSource;

    public ReportService(@Qualifier("reportingDataSource") DataSource ds) {
        this.dataSource = ds;  // Specifies which DataSource by name
    }
}
